def count_nums(arr):
    def digit_sum(n):
        if n == 0:
            return 0
        sign = 1 if n > 0 else -1
        n = abs(n)
        total = 0
        first = True
        while n > 0:
            d = n % 10
            if first:
                total += sign * d
                first = False
            else:
                total += d
            n //= 10
        return total

    return sum(1 for x in arr if digit_sum(x) > 0)
